class Solution(object):
    def singleNumber(self, nums):
        """
        :type nums: List[int]
        :rtype: List[int]
        """
        xor = 0
        for num in nums:
            xor = xor^num
        lastbit = xor&(-xor)
        filtered = filter(lambda x: x&lastbit, nums)
        n = 0
        for num in filtered:
            n = n ^ num
        return (n, n^xor)

class Solution(object):
    def singleNumber(self, nums):
        """
        :type nums: List[int]
        :rtype: List[int]
        """
        xor_sum = 0
        for num in nums:
            xor_sum = xor_sum ^ num
        tag = xor_sum & (-xor_sum)
        num1 = num2 = 0
        for num in nums:
            if num & tag:
                num1 = num1 ^ num
            else:
                num2 = num2 ^ num
        return [num1, num2]
